UPDATE products SET discovery_json='{"intro": "Winter Is Coming aduce o atmosferă de fantasy medieval într-un obiect mic, din lemn. Detaliile întunecate și tema muzicală îl fac ușor de asociat cu pasiunea unui fan Game of Thrones, fără să ocupe mult spațiu pe raft sau pe birou.", "audience": "Pentru fanii Game of Thrones, cititorii de fantasy și colecționarii care preferă un decor sobru. Verifică fotografiile pentru ilustrația exactă de pe capac și forma mecanismului.", "occasions": ["Crăciun: tema de iarnă și atmosfera modelului se potrivesc unui cadou ales pentru un fan al seriei.", "Aniversare: o amintire muzicală pentru un prieten pasionat de universuri medievale.", "Secret Santa: potrivit când știi deja serialul preferat al destinatarului și verifici bugetul disponibil."], "moments": ["Lângă volume fantasy și alte obiecte de colecție, într-o bibliotecă personală.", "Pe birou, pentru o scurtă pauză în care mecanismul rămâne vizibil și se aude doar prin rotirea manivelei."], "guides": ["craciun", "secret-santa"]}',version=version+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE slug='got-winter' AND discovery_json IS NULL;
